// src/pages/CashBackPage/SimpleCashBackPage.jsx
import React from 'react';
import styles from './CashBackPage.module.css';
import productImage from '../../Components/assets/placeholder.js';

// Simple CashBack Card component that doesn't rely on context
const SimpleCashBackCard = ({ discount, name, image, link }) => {
  return (
    <div className={styles.card || "card"}>
      <div className={styles.discountBadge || "discount-badge"}>{discount}</div>
      <div className={styles.imageContainer || "image-container"}>
        <img src={image} alt={name} className={styles.productImage || "product-image"} />
      </div>
      <h3 className={styles.productName || "product-name"}>{name}</h3>
      <a href={link} className={styles.viewDealButton || "view-deal-button"}>View Deal</a>
    </div>
  );
};

// Fallback data
const fallbackOffers = [
  { id: 1, discount: '53% OFF', name: 'Pokemon Construx Charizard...', image: productImage, link: '#' },
  { id: 2, discount: '43% OFF', name: 'Amazon Fire TV 4-Series 4K HDR Smart TV', image: productImage, link: '#' },
  { id: 3, discount: '38% OFF', name: 'Panasonic Nanoe Oscillating QuickDry Nozzle...', image: productImage, link: '#' },
  { id: 4, discount: '35% OFF', name: 'Apple AirTag Tracker (4-Pack)', image: productImage, link: '#' },
  { id: 5, discount: '40% OFF', name: 'Sample Product 5', image: productImage, link: '#' },
  { id: 6, discount: '25% OFF', name: 'Wireless Headphones', image: productImage, link: '#' },
  { id: 7, discount: '30% OFF', name: 'Smart Watch', image: productImage, link: '#' },
  { id: 8, discount: '45% OFF', name: 'Bluetooth Speaker', image: productImage, link: '#' },
];

// Simple CashBack Page that doesn't rely on context
const SimpleCashBackPage = () => {
  return (
    <div className={styles.container || "container"}>
      <div className={styles.header || "header"}>
        <h1>Cash Back Offers</h1>
        <p>Find the best cash back deals from your favorite stores.</p>
      </div>
      
      <div className={styles.filters || "filters"}>
        <h2>Top Cash Back Offers</h2>
      </div>
      
      <div className={styles.grid || "grid"}>
        {fallbackOffers.map(offer => (
          <SimpleCashBackCard
            key={offer.id}
            discount={offer.discount}
            name={offer.name}
            image={offer.image}
            link={offer.link}
          />
        ))}
      </div>
      
      <div className={styles.loadMore || "load-more"}>
        <button className={styles.loadMoreButton || "load-more-button"}>
          Load More
        </button>
      </div>
    </div>
  );
};

export default SimpleCashBackPage;
